package ua.empirecraft.feudal;

import java.math.*;
import java.nio.file.*;
import java.util.*;
import static ua.empirecraft.feudal.FeudalTests.*;
import static ua.empirecraft.feudal.CurrencyTests.*;
import static ua.empirecraft.feudal.Database.*;
import static ua.empirecraft.feudal.Model.*;
import static ua.empirecraft.feudal.CurrencyService.*;

/** Real-H2 settlement, failure injection, monetary invariants and adversarial round trips. */
public final class CurrencyExchangeTests {
    static CurrencyExchange exchange(Fixture f)throws Exception{return CurrencyMarketTests.market(f).exchange;}
    static CurrencyExchange setup(Fixture f)throws Exception{currency(f,a,"n:A","KRN",1000,100000);currency(f,b,"n:B","SOL",1000,100000);f.s.transfer(a,"e:n:A","p:"+D,"KRN",50000);return exchange(f);}
    static CurrencyExchange.Policy plain(){return new CurrencyExchange.Policy(0,0,0,0,10000,10000,0,MAX_MONEY);}
    static void set(CurrencyExchange x,String code,CurrencyExchange.Policy p)throws Exception{x.db.execute("MERGE INTO exchange_policy KEY(code) VALUES(?,?)",code,p.encode());}
    static void plain(CurrencyExchange x)throws Exception{set(x,"KRN",plain());set(x,"SOL",plain());}
    static CurrencyExchange.Trade swap(Fixture f,CurrencyExchange x,String from,String to,String n)throws Exception{var q=x.quote(from,to,n);var result=x.execute(d,from,to,n,ZERO,q.stamp());f.time.value+=5000;clean(f);return result;}
    static void near(BigDecimal a,BigDecimal b,String tolerance){if(a.subtract(b).abs().compareTo(new BigDecimal(tolerance))>0)throw new AssertionError(a+" != "+b);}
    public static void main(String[] args)throws Exception{
        Class.forName("org.h2.Driver");count=0;
        test("Integral R/M curve is reversible with conservative decimal rounding",()->{BigDecimal r=gold("1000"),paid=CurrencyCurve.sell(r,100000,10000);near(paid,new BigDecimal("95.162581964040"),"0.000000000001");long bought=CurrencyCurve.buy(r.subtract(paid),100000,paid,100000);eq(bought,9999L);requireTest(CurrencyCurve.cost(r.subtract(paid),100000,bought).compareTo(paid)<=0);});
        test("Treasury swap moves both reserves and coins; it never emits or proportionally burns principal",()->{try(var f=new Fixture()){var x=setup(f);plain(x);var q=swap(f,x,"KRN","SOL","10");eq(number(f.s.currency("KRN"),"supply"),100000L);eq(number(f.s.currency("SOL"),"supply"),100000L);eq(f.s.balance("e:n:A","KRN"),51000L);eq(f.s.balance("e:n:B","SOL"),100000L-q.targetGross());requireTest(f.s.currencies.value("KRN").compareTo(gold("1"))<0);requireTest(f.s.currencies.value("SOL").compareTo(gold("1"))>0);}});
        test("Both gold fees share one gross base and only the separate coin fees burn supply",()->{try(var f=new Fixture()){var x=setup(f);set(x,"KRN",new CurrencyExchange.Policy(50,50,10,10,1000,3000,2000,100000));set(x,"SOL",new CurrencyExchange.Policy(200,200,10,10,1000,3000,2000,100000));var q=swap(f,x,"KRN","SOL","10");eq(q.feeA(),CurrencyExchange.fee(q.gross(),50));eq(q.feeB(),CurrencyExchange.fee(q.gross(),200));eq(f.s.currencies.reserve("KRN"),gold("1000").subtract(q.gross()).add(q.feeA()));eq(f.s.currencies.reserve("SOL"),gold("1000").add(q.cost()).add(q.feeB()));eq(number(f.s.currency("KRN"),"supply"),100000-q.sourceBurn());eq(number(f.s.currency("SOL"),"supply"),100000-q.targetBurn());}});
        test("A gold purchase needs real treasury stock and cannot mint around a liquidity shortage",()->{try(var f=new Fixture()){var x=setup(f);f.gold(d,100);f.s.transfer(b,"e:n:B","p:"+B,"SOL",100000);no(()->x.execute(d,"@GOLD","SOL","1",ZERO,null));eq(f.s.currencies.goldBalance("p:"+D),gold("100"));eq(number(f.s.currency("SOL"),"supply"),100000L);clean(f);}});
        test("min_out rejection atomically preserves reserves, balances, cooldowns and audit",()->{try(var f=new Fixture()){var x=setup(f);long logs=x.journal("KRN",0).size();no(()->x.execute(d,"KRN","SOL","10",gold("100"),null));eq(f.s.balance("p:"+D,"KRN"),50000L);eq(f.s.currencies.reserve("KRN"),gold("1000"));eq((long)x.journal("KRN",0).size(),logs);eq(f.db.query("SELECT * FROM exchange_cooldown").size(),0);clean(f);}});
        test("A database failure rolls back both currencies, fees, burns, window use and public logs",()->{try(var f=new Fixture()){var x=setup(f);f.db.execute("CREATE TRIGGER reject_swap BEFORE INSERT ON exchange_trades FOR EACH ROW CALL 'ua.empirecraft.feudal.CurrencyMarketTests$Reject'");try{x.execute(d,"KRN","SOL","10",ZERO,null);throw new AssertionError();}catch(IllegalStateException expected){}eq(f.s.balance("p:"+D,"KRN"),50000L);eq(f.db.query("SELECT * FROM exchange_flows").size(),0);eq(f.db.query("SELECT * FROM exchange_public").size(),0);eq(f.db.query("SELECT * FROM exchange_cooldown").size(),0);clean(f);}});
        test("Five-second cooldown covers all swaps and redemption requests and survives rejection",()->{try(var f=new Fixture()){var x=setup(f);x.execute(d,"KRN","SOL","1",ZERO,null);no(()->x.execute(d,"KRN","SOL","1",ZERO,null));no(()->x.request(d,"p:"+D,"KRN",100,ZERO,null));f.time.value+=4999;no(()->x.execute(d,"KRN","SOL","1",ZERO,null));f.time.value++;x.execute(d,"KRN","SOL","1",ZERO,null);clean(f);}});
        test("Only the current ruler or a current appointed citizen can schedule policy",()->{try(var f=new Fixture()){var x=setup(f);no(()->x.schedule(admin,"KRN",plain()));no(()->x.schedule(e,"KRN",plain()));x.market.banker(a,"n:A",E,true);x.schedule(e,"KRN",plain());eq(x.policy("KRN"),CurrencyExchange.DEFAULT);no(()->x.schedule(a,"KRN",plain()));f.time.value+=CurrencyExchange.HOUR-1;eq(x.policy("KRN"),CurrencyExchange.DEFAULT);f.time.value++;x.tick();eq(x.policy("KRN"),plain());requireTest(x.journal("KRN",0).toString().contains("POLICY_ACTIVE"));}});
        test("Succession or revoked banker authority voids a pending change instead of applying it",()->{try(var f=new Fixture()){var x=setup(f);x.market.banker(a,"n:A",E,true);x.schedule(e,"KRN",plain());x.market.banker(a,"n:A",E,false);f.time.value+=CurrencyExchange.HOUR;x.tick();eq(x.policy("KRN"),CurrencyExchange.DEFAULT);eq(f.db.query("SELECT * FROM exchange_pending").size(),0);}});
        test("A captured quote cannot silently cross a matured fee policy",()->{try(var f=new Fixture()){var x=setup(f);var q=x.quote("KRN","SOL","1");x.schedule(a,"KRN",plain());f.time.value+=CurrencyExchange.HOUR;x.tick();no(()->x.execute(d,"KRN","SOL","1",ZERO,q.stamp()));clean(f);}});
        test("Trade cap and the reserve-ratio circuit breaker also protect direct redemption",()->{try(var f=new Fixture()){var x=setup(f);no(()->x.quote("KRN","SOL","200"));no(()->x.request(d,"p:"+D,"KRN",20000,ZERO,null));set(x,"KRN",new CurrencyExchange.Policy(0,0,0,0,10000,10000,9990,100000));no(()->x.quote("KRN","SOL","10"));clean(f);}});
        test("Rolling 24-hour reserve cap aggregates trades and manual funding cannot reset it",()->{try(var f=new Fixture()){var x=setup(f);set(x,"KRN",new CurrencyExchange.Policy(0,0,0,0,1000,3000,0,MAX_MONEY));set(x,"SOL",plain());for(int i=0;i<3;i++)swap(f,x,"KRN","SOL","100");no(()->x.quote("KRN","SOL","100"));f.gold(a,1);f.back(a,"KRN","1");no(()->x.quote("KRN","SOL","100"));f.time.value+=CurrencyExchange.DAY+1;swap(f,x,"KRN","SOL","100");}});
        test("Queued coins remain in total supply and cannot be spent twice before settlement",()->{try(var f=new Fixture()){var x=setup(f);String id=x.request(d,"p:"+D,"KRN",1000,ZERO,null);var row=f.db.one("SELECT * FROM exchange_redemptions WHERE id=?",id);eq(f.s.balance("p:"+D,"KRN"),49000L);eq(f.s.balance("x:"+id,"KRN"),1000L);eq(number(f.s.currency("KRN"),"supply"),100000L);requireTest(number(row,"due")-f.s.now()>=600000);f.time.value=number(row,"due")-1;x.tick();eq(f.s.currencies.payable(D),ZERO);x.cancel(d,id);eq(f.s.balance("p:"+D,"KRN"),50000L);no(()->x.cancel(d,id));clean(f);}});
        test("Redemption quota counts pending and cancelled submissions over a rolling day",()->{try(var f=new Fixture()){var x=setup(f);set(x,"KRN",new CurrencyExchange.Policy(0,0,0,0,1000,3000,0,1000));String id=x.request(d,"p:"+D,"KRN",600,ZERO,null);x.cancel(d,id);f.time.value+=5000;no(()->x.request(d,"p:"+D,"KRN",600,ZERO,null));f.time.value+=CurrencyExchange.DAY+1;x.request(d,"p:"+D,"KRN",600,ZERO,null);clean(f);}});
        test("Two claims share insufficient window liquidity proportionally rather than FIFO",()->{try(var f=new Fixture()){var x=setup(f);set(x,"KRN",new CurrencyExchange.Policy(0,0,0,0,1000,1000,0,MAX_MONEY));f.s.transfer(a,"e:n:A","p:"+E,"KRN",8000);String one=x.request(d,"p:"+D,"KRN",8000,ZERO,null),two=x.request(e,"p:"+E,"KRN",8000,ZERO,null);f.time.value=number(f.db.one("SELECT * FROM exchange_redemptions WHERE id=?",one),"due");x.tick();near(f.s.currencies.payable(D),gold("50"),"0.000000000002");eq(f.s.currencies.payable(D),f.s.currencies.payable(E));eq(string(f.db.one("SELECT * FROM exchange_redemptions WHERE id=?",two),"status"),"PAID");x.tick();clean(f);}});
        test("A batch below each claim's min_out refunds every coin and transfers no gold",()->{try(var f=new Fixture()){var x=setup(f);set(x,"KRN",new CurrencyExchange.Policy(0,0,0,0,1000,1000,0,MAX_MONEY));f.s.transfer(a,"e:n:A","p:"+E,"KRN",8000);String id=x.request(d,"p:"+D,"KRN",8000,gold("60"),null);x.request(e,"p:"+E,"KRN",8000,gold("60"),null);f.time.value=number(f.db.one("SELECT * FROM exchange_redemptions WHERE id=?",id),"due");x.tick();eq(f.s.balance("p:"+D,"KRN"),50000L);eq(f.s.balance("p:"+E,"KRN"),8000L);eq(f.s.currencies.reserve("KRN"),gold("1000"));clean(f);}});
        test("A failed batch update rolls back escrow, gold, burn and status before safe retry",()->{try(var f=new Fixture()){var x=setup(f);String id=x.request(d,"p:"+D,"KRN",1000,ZERO,null);f.time.value=number(f.db.one("SELECT * FROM exchange_redemptions WHERE id=?",id),"due");f.db.execute("CREATE TRIGGER reject_clear BEFORE UPDATE ON exchange_redemptions FOR EACH ROW CALL 'ua.empirecraft.feudal.CurrencyMarketTests$Reject'");try{x.tick();throw new AssertionError();}catch(IllegalStateException expected){}eq(f.s.balance("x:"+id,"KRN"),1000L);eq(f.s.currencies.payable(D),ZERO);f.db.execute("DROP TRIGGER reject_clear");x.tick();BigDecimal paid=f.s.currencies.payable(D);x.tick();eq(f.s.currencies.payable(D),paid);clean(f);}});
        test("Gold redemption cannot bypass delay, fees, quota or exchange limits",()->{try(var f=new Fixture()){var x=setup(f);no(()->x.execute(d,"KRN","@GOLD","1",ZERO,null));f.s.currencies.redeem(d,"p:"+D,"KRN",100);eq(f.s.currencies.payable(D),ZERO);eq(x.requests(d).size(),1);eq(x.requests(e).size(),0);clean(f);}});
        test("Zero-fee two-way and triangular cycles never increase liquidatable gold wealth",()->{for(boolean triangle:List.of(false,true)){try(var f=new Fixture()){currency(f,c,"n:C","ROM",1000,100000);var x=setup(f);plain(x);set(x,"ROM",plain());BigDecimal baseline=CurrencyCurve.sell(gold("1000"),100000,10000);var one=swap(f,x,"KRN","SOL","100");String source="SOL";long amount=one.targetGross();if(triangle){var two=swap(f,x,"SOL","ROM",format(amount));source="ROM";amount=two.targetGross();}var last=swap(f,x,source,"KRN",format(amount));BigDecimal wealth=CurrencyCurve.sell(f.s.currencies.reserve("KRN"),100000,last.targetGross()).add(f.s.currencies.payable(D));requireTest(wealth.compareTo(baseline.add(new BigDecimal("0.00000000001")))<=0);}}});
        test("Public exchange journals omit traders while funding and policy changes identify managers",()->{try(var f=new Fixture()){var x=setup(f);x.names=id->id.equals(A)?"Mayor":"Citizen";swap(f,x,"KRN","SOL","1");String publicRows=x.journal("KRN",0).toString();requireTest(!publicRows.contains(D)&&!publicRows.contains("Citizen"));eq(string(f.db.one("SELECT * FROM exchange_trades"),"person"),D);f.gold(a,1);f.back(a,"KRN","1");requireTest(x.journal("KRN",0).toString().contains("Mayor"));x.schedule(a,"KRN",plain());requireTest(x.journal("KRN",0).toString().contains("Було:"));clean(f);}});
        test("Pending policies, cooldowns and redemption escrow survive a real disk restart",()->{Path dir=Files.createTempDirectory("currency-exchange-");String url="jdbc:h2:"+dir.resolve("db")+";DATABASE_TO_LOWER=TRUE";String id;long due;try{try(var f=new Fixture(url)){var x=setup(f);x.schedule(a,"KRN",plain());id=x.request(d,"p:"+D,"KRN",1000,ZERO,null);due=number(f.db.one("SELECT * FROM exchange_redemptions WHERE id=?",id),"due");}try(var f=new Fixture(url)){var x=exchange(f);no(()->x.request(d,"p:"+D,"KRN",100,ZERO,null));eq(f.s.balance("x:"+id,"KRN"),1000L);f.time.value=due;x.tick();eq(string(f.db.one("SELECT * FROM exchange_redemptions WHERE id=?",id),"status"),"PAID");f.time.value+=CurrencyExchange.HOUR;x.tick();eq(x.policy("KRN"),plain());clean(f);}}finally{remove(dir);}});
        test("Policy inputs reject invalid percentages, missing limits and fractional sub-cent quotas",()->{no(()->CurrencyExchange.parse("1;1;0;0;0;30;20;100"));no(()->CurrencyExchange.parse("11;1;0;0;10;30;20;100"));no(()->CurrencyExchange.parse("1;1;0;0;10;30;20;0.001"));no(()->CurrencyExchange.bps("1e999999999"));no(()->CurrencyExchange.bps("1e-999999999"));no(()->CurrencyExchange.bps(null));eq(CurrencyExchange.parse("0.5;3;0.1;0.2;10;30;20;1000").buy(),50);});
        test("Missing, sub-cent and overflowing gold redenominations pause tribute safely",()->{for(int scenario=0;scenario<3;scenario++){try(var f=new Fixture()){
            currency(f,a,"n:A","KRN",1000,100000);currency(f,b,"n:B","SOL",1000,100000);long amount=scenario==2?1000L:100L;f.link(a,"n:B","n:A",amount,"SOL",b);var x=exchange(f);
            String changed=scenario==0?"SOL":"KRN",person=scenario==0?B:A;BigDecimal remaining=scenario==0?gold("0.001"):scenario==1?ZERO:gold("0.000000001");BigDecimal removed=f.s.currencies.reserve(changed).subtract(remaining);f.s.currencies.setGold("r:"+changed,remaining);f.s.currencies.setGold("p:"+person,f.s.currencies.goldBalance("p:"+person).add(removed));
            f.time.value+=7*FeudalService.DAY;f.s.tick();eq(string(f.s.contract("n:B"),"code"),"SOL");eq(number(f.s.contract("n:B"),"amount"),amount);eq(f.db.query("SELECT * FROM invoices").size(),0);eq(f.db.query("SELECT * FROM currency_tribute_pauses").size(),1);clean(f);
        }}});
        test("Legacy BASE currencies reject physical gold reserve intents before inventory mutation",()->{try(var f=new Fixture()){
            f.s.createCurrency(a,"n:A","KRN","Крона","K");f.db.execute("UPDATE currencies SET backing='LEGACY_BASE' WHERE code='KRN'");var x=exchange(f);f.gold(a,1);no(()->f.s.currencies.prepareGold(a,"IN","r:KRN",1,"before","after"));eq(f.db.query("SELECT * FROM gold_ops WHERE status='PREPARED'").size(),0);eq(f.s.currencies.goldBalance("p:"+A),gold("1"));clean(f);
        }});
        System.out.println("Treasury exchange scenarios: "+count);
    }
    static void requireTest(boolean test){if(!test)throw new AssertionError("Invariant failed");}
}

